-- 10,000 active products: skewed categories, bilingual names, mixed stock.
INSERT INTO products (id, brand_id, category_id, slug, name, name_en, summary, summary_en, status, published_at)
SELECT
    ('3' || lpad(gs::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    (ARRAY['00000064-0000-4000-8000-000000000064'::uuid,'00000065-0000-4000-8000-000000000065'::uuid,'00000066-0000-4000-8000-000000000066'::uuid,'00000067-0000-4000-8000-000000000067'::uuid,'00000068-0000-4000-8000-000000000068'::uuid])[1 + (gs % 5)],
    CASE
        WHEN (gs % 100) < 35 THEN '000000c9-0000-4000-8000-0000000000c9'::uuid
        WHEN (gs % 100) < 55 THEN '000000ca-0000-4000-8000-0000000000ca'::uuid
        WHEN (gs % 100) < 67 THEN '000000cb-0000-4000-8000-0000000000cb'::uuid
        WHEN (gs % 100) < 82 THEN '000000cc-0000-4000-8000-0000000000cc'::uuid
        WHEN (gs % 100) < 90 THEN '000000cd-0000-4000-8000-0000000000cd'::uuid
        WHEN (gs % 100) < 95 THEN '000000cf-0000-4000-8000-0000000000cf'::uuid
        WHEN (gs % 100) < 100 THEN '000000d0-0000-4000-8000-0000000000d0'::uuid
        ELSE '000000d0-0000-4000-8000-0000000000d0'::uuid
    END,
    'scale-' || lpad(gs::text, 5, '0'),
    CASE WHEN gs % 4 = 0 THEN '量測商品 ' || gs::text ELSE 'Scale product ' || gs::text END,
    CASE WHEN gs % 4 = 0 THEN 'Scale product ' || gs::text ELSE '量測商品 ' || gs::text END,
    '量測摘要 ' || gs::text,
    'Scale summary ' || gs::text,
    'active',
    now() - ((gs % 365) || ' days')::interval
FROM generate_series(1, 10000) gs;

-- One or two variants per product; every third product carries a markdown.
INSERT INTO product_variants (id, product_id, sku, price_cents, compare_at_price_cents, stock_quantity, safety_stock, position)
SELECT
    ('4' || lpad((gs * 10 + v)::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    ('3' || lpad(gs::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    'SC-' || lpad(gs::text, 5, '0') || '-' || v,
    500000 + (gs % 500) * 10000 + v * 50000,
    CASE WHEN gs % 3 = 0 THEN 600000 + (gs % 500) * 10000 + v * 50000 ELSE NULL END,
    CASE
        WHEN gs % 9 = 0 THEN 0
        WHEN gs % 5 = 2 AND v = 0 THEN 2
        ELSE 5 + (gs % 20)
    END,
    2,
    v
FROM generate_series(1, 10000) gs
CROSS JOIN generate_series(0, 1) v
WHERE v = 0 OR gs % 2 = 0;

INSERT INTO product_images (id, product_id, storage_key, alt_text, alt_text_en, width, height, position)
SELECT
    ('5' || lpad(gs::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    ('3' || lpad(gs::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    'scale-' || lpad(gs::text, 5, '0') || '-01.webp',
    '量測商品 ' || gs::text || ' 商品照',
    'Scale product ' || gs::text || ' photo',
    1600, 1200, 0
FROM generate_series(1, 10000) gs;

INSERT INTO product_reviews (id, product_id, user_id, rating, title, body, is_verified_purchase)
SELECT
    ('6' || lpad((gs * 3 + r)::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    ('3' || lpad(gs::text, 7, '0') || '-0000-4000-8000-000000000000')::uuid,
    NULL,
    3 + (r % 3),
    '量測評論 ' || gs::text || '-' || r::text,
    'Scale review body',
    false
FROM generate_series(1, 10000) gs
CROSS JOIN generate_series(0, 2) r
WHERE gs % 2 = 0 OR r = 0;

